import type { AccordionTitleProps } from "../accordion.types";

import { forwardRef } from "react";
import { clsx } from "clsx";

import { AccordionClasses } from "../accordion.styles";

export const AccordionTitle = forwardRef<HTMLSpanElement, AccordionTitleProps>(
  ({ children, className, ...props }, ref) => {
    return (
      <span ref={ref} className={clsx(AccordionClasses.title, className)} {...props}>
        {children}
      </span>
    );
  },
);

AccordionTitle.displayName = "Accordion.Title";
